missing = Complement[Range@10, b[[All, 1]]];
Fold[Insert[#1, {#2, 1}, #2] &, b, missing]

This gives:
{{1, 1}, {2, 2}, {3, 3}, {4, 1}, {5, 5}, {6, 6}, {7, 1}, {8, 8}, {9, 1}, {10, 10}}

