  }],
 {{s, 0}, 0, 20, .01},
 {{r, 0}, 0, 1, .01},
 Initialization -> (y[t_, r_, x0_] := 1/(1 + (1/x0 - 1) Exp[-r t]))
]

This supports varying r and using the symbol-based parameterization.

